style.css:
@-moz-document domain("roblox.com") {
/* Alterar texto "Premium" */
    .premium-icon::after {
        content: "Builders Club";
        font-size: inherit;
        color: inherit;
    }
    /* Substituir ícone do Premium por outro estilo */
    .premium-icon {
        background-image: url("https://i.imgur.com/X7fUSlH_d.webp?maxwidth=760&fidelity=grand");
        background-size: contain;
    }
    /* Ajustar possíveis outros textos Premium */
    .text-premium {
        content: "Builders Club";
        color: inherit;
    }
}
